PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://brickgov/def/ref#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?id ?ts WHERE {
  ?p a brick:AirTemperatureSensor ;
     rdfs:label ?id ;
     ref:hasTimeseriesId ?ts .
  FILTER(
    (CONTAINS(STR(?id), "Perimeter_ZN_3")) ||
    (CONTAINS(STR(?id), "Perimeter_ZN_2"))
  )
}

